Translate("deDE", "winterspring", {
	title = "Winterspring",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Winterspring ist das gefrorene Dach des nördlichen {link:kalimdor}Kalimdor{/link}, ein Hochland aus Schneefeldern, Kiefertälern und blauem Eis jenseits der Tunnel der {link:timbermaw-furbolgs}Holzschlund{/link}. Nur wenige Lande der Welt sind so kalt, und nur wenige sind so voller alter Dinge. Elfenruinen schlafen unter den Schneewehen. Ein See birgt unter seinem Eis die Splitter einer gestohlenen Reliquie. Drachen des blauen Schwarms wachen aus Höhlen in den Hügeln. Doch der Schnee ist nicht still. Die {link:furbolgs}Furbolgs{/link} der {link:winterfall-furbolgs}Winterfelle{/link} sind wahnsinnig geworden, die Eulenbestien des Ostens sind verwildert, und im äußersten Süden wird die Luft warm und faulig, wo noch immer Dämonen verweilen.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Keine Chronik verzeichnet das Jahr, in dem die {link:night-elves}Nachtelfen{/link} zuerst in diesen Tälern bauten. Gewiss ist, dass sie es lange vor der {link:great-sundering}Großen Zerschlagung{/link} taten. Hochgeborene lebten am {link:lake-kel-theril}Kel'Therilsee{/link}, und die Ruinen ihrer Hallen stehen dort noch immer. Die Elfen erinnern sich auch an eine Tat ihrer Hohepriesterin. Nach dem Bericht der Wintersäblerausbilder rettete {link:tyrande-whisperwind}Tyrande Whisperwind{/link} vor etwa viertausend Jahren die Königin der Frostsäbler vor wütenden Riesen, und seither sind die großen Katzen von Winterspring Freunde der Elfen. Über die Wildkin sagen die Druiden nur, dass sie Geschöpfe {red:elune}Elunes{/red} sind, eingesetzt, um ihre heiligsten Stätten zu bewachen, und in den Hügeln des Ostens gibt es solche Stätten.]=],
		},
		{
			title = "Die heutige Zeit",
			text = [=[Winterspring gehört keiner Nation. Die {link:night-elves}Nachtelfen{/link} unterhalten ein kleines Dorf in {link:starfall-village}Starfall{/link}, und die Frostsäblerausbilder halten sich an ihren Felsen im Norden. Das Herz des Landes aber ist {link:everlook}Everlook{/link}, eine Goblinstadt des {link:steamwheedle-cartel}Steamwheedle-Kartells{/link}, in der {link:alliance}Allianz{/link} und {link:horde}Horde{/link} unter den Augen der Schläger des Kartells handeln und einander keine Fragen stellen. Gelehrte sind zu den heißen Quellen gekommen, {link:dwarves}Zwerge{/link} der {link:explorers-league}Forscherliga{/link} graben zwischen den Ruinen, und die {link:argent-dawn}Argentumdämmerung{/link} unterhält einen Gesandten in der Stadt. Sie alle teilen dieselben Sorgen. Der {link:winterfall-furbolgs}Stamm der Winterfelle{/link}, einst sanftmütig, hat begonnen, ein grünes Feuerwasser zu trinken, das mit dem Makel des {link:felwood}Teufelswalds{/link} gebraut wird, und sie greifen alle an, die sich nähern. Und in der flüsternden Schlucht, am südlichen Rand des Landes und unter den Höhen des {link:mount-hyjal}Berges Hyjal{/link}, hausen noch immer Dämonen der {link:burning-legion}Brennenden Legion{/link}, und es heißt, ihre Gegenwart wärme die Quellen selbst.]=],
		},
		{
			title = "Bewohner",
			text = [=[• {b}Die Goblins von {link:everlook}Everlook{/link}.{/b} Händler, Schmiede und Gastwirte des {link:steamwheedle-port}Steamwheedle{/link}-Kartells, bewacht von den Schlägern von Everlook.
• {b}Die {link:night-elves}Nachtelfen{/link} von {link:starfall-village}Starfall{/link}.{/b} Eine Handvoll Elfen, die über die Ruinen ihrer Vorfahren wachen.
• {b}Die {link:furbolgs}Furbolgs{/link} der {link:winterfall-furbolgs}Winterfelle{/link}.{/b} Einst die Verbündeten der {link:timbermaw-furbolgs}Holzschlund{/link}, nun wahnsinnig und gewalttätig unter ihrem Oberhäuptling.
• {b}Die Holzschlund.{/b} Die letzten Furbolgs des Nordens, die bei Verstand sind; sie halten die Tunnel zwischen Winterspring und dem {link:felwood}Teufelswald{/link}.
• {b}Der blaue Drachenschwarm.{/b} Seine Drachen und Drachenbrut hüten die Höhlen von {link:mazthoril}Mazthoril{/link}.
• {b}Bestien des Schnees.{/b} Frostsäbler, Splitterzahnbären, Frostwindchimären, Eisdistelyetis und rasende Eulenbestien.
• {b}Die Frostschlägerriesen.{/b} Riesen aus lebendem Eis, die {link:stranglethorn-vale}das Tal{/link} der {link:frostwhisper-gorge}Frostwhisperschlucht{/link} halten.
• {b}Dämonen.{/b} Die {link:lady-hederine}Hederine{/link} und ihre Herrin spuken in der flüsternden Schlucht.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Die Hochgeborenen.{/b} Vor der {link:great-sundering}Zerschlagung{/link} stahlen die Hochgeborenen einen heiligen Kristall und versuchten, am {link:lake-kel-theril}Kel'Therilsee{/link} seine Macht auszusaugen. Die Reliquie zersprang, und ihre Geister bleiben an den Ort gebunden.
• {b}Die Frostsäblerkönigin.{/b} {link:tyrande-whisperwind}Tyrande Whisperwind{/link} rettete die Königin der Frostsäbler vor den Riesen, und die Frostsäbler schlossen sich den {link:night-elves}Nachtelfen{/link} an.
• {b}Der Dritte Krieg.{/b} Die {link:burning-legion}Brennende Legion{/link} kam zum {link:mount-hyjal}Berg Hyjal{/link}. {link:archimonde}Archimonde{/link} fiel in der {link:battle-of-mount-hyjal}Schlacht am Berg Hyjal{/link}, doch Dämonen verweilen noch immer in der flüsternden Schlucht, am nördlichen Fuß des Berges. Keine Chronik sagt, wann sie kamen.
• {b}Die heutige Zeit.{/b} Das Kartell hat {link:everlook}Everlook{/link} zum einzigen warmen Herd im Norden gemacht, und alle Sorgen des Schnees ziehen durch seine Tore.]=],
		},
		{
			title = "Überlieferungen des Schnees",
			text = [=[• Gäste im Gasthaus von {link:everlook}Everlook{/link} lernen schnell, einen Platz weit weg vom Ofen zu wählen.
• Die Hexendoktorin der {link:trolls}Trolle{/link} in Everlook behauptet, jede Bestie berge eine Macht, die sie E'ko nennt, und mit dem richtigen Talisman lasse sie sich einfangen.
• Ein alter Medium lebt allein in den Hügeln östlich von Everlook. Er spricht mit den Toten, und manche sagen, die Toten antworten.
• Von Frostriesen heißt es, sie verlören Eissplitter, so klar, dass sie Macht zurückwerfen, wie ein Spiegel das Licht zurückwirft.]=],
		},
	},
})

Translate("deDE", "everlook", {
	title = "Everlook",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Everlook ist eine ummauerte Goblinstadt im Herzen von {link:winterspring}Winterspring{/link} und die einzige wahre Stadt im gefrorenen Norden. Das {link:steamwheedle-cartel}Steamwheedle-Kartell{/link} herrscht über sie, und ihr Gesetz ist einfach: Wahre den Frieden und bezahle, was du nimmst. {link:alliance}Allianz{/link} und {link:horde}Horde{/link} landen hier gleichermaßen auf Greifen und Windreitern, und beide sind willkommen, solange ihre Münzen reichen. Die Schläger von Everlook halten an den Toren Ordnung. Innerhalb der Mauern gibt es ein Gasthaus, eine Bank, Schmiede und Händler. Es gibt auch seltsamere Leute: eine Hexendoktorin der {link:trolls}Trolle{/link}, eine Erfinderin mechanischer Yetis, einen Schmied der {link:thorium-brotherhood}Thoriumbruderschaft{/link} und einen Gesandten der {link:argent-dawn}Argentumdämmerung{/link}.]=],
		},
	},
})

Translate("deDE", "starfall-village", {
	title = "Starfall",
	aliases = { "Starfall" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Starfall ist eine kleine Siedlung der {link:night-elves}Nachtelfen{/link} westlich von {link:everlook}Everlook{/link}. Ihre Bewohner leben in einer Hütte zwischen den Kiefern und halten stille Wache über die Ruinen ihrer Vorfahren. {link:wynd-nightchaser}Wynd Nightchaser{/link} kennt die alten Geschichten des Landes besser als irgendjemand hier. Ein {link:dwarves}Zwerg{/link} der {link:explorers-league}Forscherliga{/link} ruht als Gast in der Hütte und hegt die Erinnerung an die Wildkin, die sein Lager zerstörten. Reisende aus {link:darnassus}Darnassus{/link} und dem {link:felwood}Teufelswald{/link} kommen zuerst nach Starfall, denn es ist das Tor, durch das die Elfen die Geheimnisse von {link:winterspring}Winterspring{/link} erfahren.]=],
		},
	},
})

Translate("deDE", "frostfire-hot-springs", {
	title = "Die heißen Quellen von Frostfire",
	aliases = { "Frostfire" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Im Westen von {link:winterspring}Winterspring{/link}, nicht weit von den Tunneln der {link:timbermaw-furbolgs}Holzschlund{/link}, dampfen warme Becken im Schnee. Dies sind die heißen Quellen von Frostfire. Kein Vulkan ist in ihrer Nähe, und die Gelehrte {link:donova-snowden}Donova Snowden{/link}, die neben ihnen lagert, glaubt, dass ihre Wärme von etwas Dunklerem weit im Süden herrührt. Die {link:furbolgs}Furbolgs{/link} der {link:winterfall-furbolgs}Winterfelle{/link} bewachen die größeren Quellen mit seltsamer Wut. Sie haben gelernt, dass das Wasser das Gift ihres grünen Feuerwassers mildert, und sie lassen niemanden sonst in die Nähe.]=],
		},
	},
})

Translate("deDE", "timbermaw-post", {
	title = "Holzschlundposten",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Holzschlundposten liegt am westlichen Rand von {link:winterspring}Winterspring{/link}, wo sich die Tunnel der {link:timbermaw-hold}Holzschlundfeste{/link} zum Schnee hin öffnen. Hier halten die {link:furbolgs}Furbolgs{/link} der {link:timbermaw-furbolgs}Holzschlund{/link} am Eingang ihrer Feste Wache. Sie gewähren jenen Durchgang, denen sie vertrauen, und bekämpfen jene, denen sie nicht vertrauen. Die Holzschlund blicken voller Kummer nach Osten. Die {link:winterfall-furbolgs}Winterfelle{/link} waren einst ihre Verbündeten, und nun kommen die Läufer der Winterfelle hier vorbei und tragen Verderbnis aus dem {link:felwood}Teufelswald{/link}.]=],
		},
	},
})

Translate("deDE", "winterfall-village", {
	title = "Lager der Winterfelle",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Lager der Winterfelle ist die Heimat der {link:furbolgs}Furbolgs{/link} der {link:winterfall-furbolgs}Winterfelle{/link}, in den Hügeln östlich von {link:everlook}Everlook{/link}. Es ist ein Ort der Hütten und Totems und der Furcht. Hier erteilt der Oberhäuptling des Stammes seine Befehle, und hierher bringen die Läufer die Fässer mit grünem Feuerwasser aus dem {link:felwood}Teufelswald{/link}. Die Furbolgs des Lagers sind größer und wilder, als ihre Artgenossen es einst waren. Ihre Schamanen und Ursa greifen alles an, was sich nähert, Tier oder Reisenden.]=],
		},
	},
})

Translate("deDE", "lake-kel-theril", {
	title = "Kel'Therilsee",
	aliases = { "Kel'Theril", "Die Ruinen von Kel'Theril" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Kel'Therilsee ist ein gefrorener See in der Mitte von {link:winterspring}Winterspring{/link}. An seinen Ufern liegen die Ruinen der Hochgeborenen. Vor langer Zeit, vor der {link:great-sundering}Großen Zerschlagung{/link}, stahlen die Hochgeborenen dieses Ortes eine heilige Reliquie und versuchten, ihre Macht auszusaugen. Die Reliquie explodierte, und ihre Stücke sanken unter das Eis. Die Hochgeborenen wurden für ihren Hochmut verflucht. Ihre Geister wandern noch immer durch die Ruinen, trauernd und feindselig, stets auf der Suche nach den Splittern des Dings, das ihr Verderben war.]=],
		},
	},
})

Translate("deDE", "mazthoril", {
	title = "Mazthoril",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Mazthoril ist ein Geflecht eisiger Höhlen in den Hügeln südlich des Kel'Therilsees. Es ist ein Hort des blauen Drachenschwarms. Blaue Drachenbrut und arkane Bestien bewachen seine Tunnel, und kobaltblaue Runen sind in seine gefrorenen Böden eingelassen. Wer auf einer solchen Rune steht und ein Zeichen des Schwarms bei sich trägt, wird von arkaner Macht zu einem hohen Sims emporgetragen. Dort wartet {link:haleh}Haleh{/link}, die in der Welt der Sterblichen für die blauen Drachen spricht.]=],
		},
	},
})

Translate("deDE", "frostsaber-rock", {
	title = "Frostsäblerfelsen",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Frostsäblerfelsen ist eine große Landmarke im Schnee des nördlichen {link:winterspring}Winterspring{/link}, wo sich die wilden Frostsäbler versammeln. Er ist das Reich ihrer Matriarchin {link:shy-rotam}Shy-Rotam{/link}, die voller Zorn hervorkommt, wenn das Fleisch ihrer Artgenossen auf ihren Stein gelegt wird. Unterhalb des Felsens, fern jedes Dorfes, bildet {link:rivern-frostwind}Rivern Frostwind{/link} Frostsäbler zum Tragen von Reitern aus. Manchmal wandern die {link:winterfall-furbolgs}Winterfelle{/link} hierher, und Rivern würde sie gern verschwinden sehen.]=],
		},
	},
})

Translate("deDE", "owl-wing-thicket", {
	title = "Eulenflügeldickicht",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Eulenflügeldickicht zieht sich einen Grat im Südosten von {link:winterspring}Winterspring{/link} hinauf. Es ist die Heimat der Wildkin, und sie bewachen es mit einer Wut, die Gelehrte und Gräber gleichermaßen vertrieben hat. Ganz oben auf dem Grat steht ein uralter Altar der {red:elune}Elune{/red}. Sein Weg ist versiegelt, und fünf Fackeln müssen in den Höhlen brennen, bevor er sich öffnet. Die Druiden des {link:cenarion-circle}Zirkels des Cenarius{/link} sagen, die Wildkin seien erwählt worden, solche heiligen Stätten zu bewachen, und sie tun es noch immer.]=],
		},
	},
})

Translate("deDE", "ice-thistle-hills", {
	title = "Eisdistelberge",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Eisdistelberge liegen südöstlich von {link:everlook}Everlook{/link}. Die Eisdistelyetis leben in Höhlen zwischen ihnen, und ihre Patriarchen und Matriarchinnen tragen große gewundene Hörner. Ihr dickes Fell ist in Everlook begehrt, wo eine gnomische Erfinderin sehr viel davon für ein eigenes Geheimnis brauchte. Die Berge sind selbst für {link:winterspring}Winterspring{/link} kalt, und die Yetis teilen sie nicht gern.]=],
		},
	},
})

Translate("deDE", "frostwhisper-gorge", {
	title = "Frostwhisperschlucht",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Frostwhisperschlucht ist ein langes Tal im Süden von {link:winterspring}Winterspring{/link}. Die Frostschlägerriesen beherrschen es, gewaltige Geschöpfe aus lebendem Eis. Sie sind dieselben Riesen, die einst die Frostsäblerkönigin bedrohten, und sie haben {link:stranglethorn-vale}das Tal{/link} für sich genommen. Splitter klaren Eises liegen über die Schlucht verstreut. Tiefer drinnen, zwischen Ruinen, geht ein {link:satyrs}Satyr{/link} namens {link:lorax}Lorax{/link} auf und ab und murmelt, brütend über einen gebrochenen Handel.]=],
		},
	},
})

Translate("deDE", "darkwhisper-gorge", {
	title = "Die flüsternde Schlucht",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die flüsternde Schlucht liegt am südlichen Ende von {link:winterspring}Winterspring{/link}, unterhalb der Höhen des {link:mount-hyjal}Berges Hyjal{/link}. Dort weicht der Schnee schwüler Luft und einem verdunkelten Himmel. Dämonen der {link:burning-legion}Brennenden Legion{/link} hausen in der Schlucht, obwohl die Legion am Hyjal zerschlagen wurde. Die {link:lady-hederine}Hederine{/link} dienen einer Herrin namens Lady Hederine. Die Gelehrte {link:donova-snowden}Donova Snowden{/link} glaubt, dass die Gegenwart der Dämonen die Quellen von Winterspring weit im Norden wärmt.]=],
		},
	},
})

Translate("deDE", "haleh", {
	title = "Haleh",
	subtitle = "Schutzmatrone des blauen Schwarms",
	found = "Ein hoher Sims über den Höhlen von Mazthoril",
	hint = [=[Suche die, die für die blauen Drachen spricht, hoch über den Höhlen von Mazthoril.]=],
	allegiance = "Blauer Drachenschwarm",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Haleh ist ein Drache des blauen Schwarms, der Hüter der {link:arcane-magic}arkanen Magie{/link}. Ihre Artgenossen nennen sie ihre Schutzmatrone. Sie wohnt auf einem hohen Sims über den Höhlen von {link:mazthoril}Mazthoril{/link}, und nur wer mit einem Zeichen ihres Schwarms auf den kobaltblauen Runen der Höhlen steht, kann zu ihr gelangen. Sie ist stolz, kühl und nur langsam bereit zu vertrauen, und sie spricht selten über etwas anderes als die Angelegenheiten ihres Schwarms.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Die Aspekte haben den Drachenschwärmen befohlen, sich aus den Angelegenheiten der Sterblichen herauszuhalten. Haleh hält sich an dieses Gebot, wo sie kann. Doch sie weiß, dass die Welt es nicht immer zulässt, am wenigsten, wenn einer der Schwärme es mit Verachtung missachtet. Durch sie leihen die blauen Drachen den Sterblichen ihre Macht gegen die schwarze Brut von {link:deathwing}Todesschwinge{/link}.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie wacht über {link:mazthoril}Mazthoril{/link}, den Hort des blauen Schwarms.
• Sie empfängt die Schuppe von Awbee, einem in der Blackrockspitze verborgenen blauen Drachen, und liest, was Awbee dort gesehen hat.
• Sie bietet Sterblichen die Macht des blauen Schwarms gegen die Brut von {link:deathwing}Todesschwinge{/link} an.
• Sie schickt ihre Erwählten mit ihrer eigenen arkanen Macht zum Bildhauer {link:jeziba}Jeziba{/link} nach {link:ruins-of-andorhal}Andorhal{/link}.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Keine Aufzeichnung nennt Halehs Alter, ihren Platz unter den blauen Drachen oder wie lange sie schon von {link:mazthoril}Mazthoril{/link} aus wacht.]=],
		},
	},
	chapters = {
		{
			title = "Die Schutzmatrone",
			hint = "Bringe eine Schuppe des blauen Schwarms nach Mazthoril.",
			text = [=[Aus den Tiefen der Blackrockspitze schickte Awbee ihrer Matrone eine Schuppe. Darin las Haleh, was Awbee an jenem verdammten Ort gesehen und gespürt hatte: die Kinder von {link:deathwing}Todesschwinge{/link} bei der Arbeit. Das durfte nicht geduldet werden. Da der Berg Nefarian Schutz bietet, konnte der blaue Schwarm ihn nicht selbst angreifen. Er konnte nur jene stärken, die es tun würden.]=],
		},
		{
			title = "Zorn des blauen Schwarms",
			hint = "Nimm die Gabe des blauen Schwarms an.",
			text = [=[Haleh warnte, dass der Weg voller Gefahren sei, und verlangte eine frei getroffene Wahl. Jenen, die annahmen, bot sie die Macht ihrer eigenen Magie an, um sie auf ihren Weg zu bringen. Sie öffnete den Weg in die Pestländer und schickte sie zu {link:jeziba}Jeziba{/link}, einem Sterblichen, den sie so weise wie die Uralten nannte.]=],
		},
		{
			title = "Das Auge des Drachen",
			hint = [=[Bringe dem blauen Schwarm ein Bruchstück vom Auge eines schwarzen Drachen.]=],
			text = [=[Das Bruchstück, das man ihr aus {link:stormwind-city}Stormwind{/link} brachte, widerte sie sofort an. Es war eine Schuppe der schwarzen Brutmutter {link:onyxia}Onyxia{/link}, zu einem Schlüssel für ihren Hort verzaubert und dann zerschmettert. Haleh konnte es wieder ganz machen, doch nur mit dem Blut eines Streiters der schwarzen Drachen: General Drakkisath, der in der Blackrockspitze über Nefarians Drachenbrut herrscht. Als das Blut kam, schmiedete sie das Drachenfeueramulett. Mit ihm konnten Onyxias Schutzzauber im {link:wyrmbog}Drachensumpf{/link} der {link:dustwallow-marsh}Marschen von Dustwallow{/link} den Weg nicht versperren.]=],
		},
	},
	mentions = {
		{ text = "Die Schutzmatrone" },
		{ text = "Zorn des blauen Schwarms" },
		{ text = "Zorn des blauen Schwarms, zu {link:jeziba}Jeziba{/link}" },
		{ text = "Das Auge des Drachen" },
		{ text = "Drachenfeueramulett" },
	},
	bonds = {
		{ id = "jeziba", name = "Jeziba", note = "sie schickt ihm Helden" },
		{ id = "awbee", name = "Awbee", note = "ein blauer Drache, der ihr in der Blackrockspitze dient" },
	},
})

Translate("deDE", "donova-snowden", {
	title = "Donova Snowden",
	subtitle = "Gelehrte der heißen Quellen",
	found = "Neben den heißen Quellen von Frostfire",
	hint = [=[Suche die Gelehrte, die im Westen neben den heißen Quellen lagert.]=],
	allegiance = "Freundin von Linken und Krakle",
	aliases = { "Donova" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Donova Snowden kam nach {link:winterspring}Winterspring{/link}, um das Geheimnis der heißen Quellen von {link:frostfire-hot-springs}Frostfire{/link} zu ergründen, wo warmes Wasser in einem Land ohne Vulkane dampft. Sie lagert noch immer neben ihnen. Sie ist geduldig, neugierig und freundlich, und sie glaubt, dass die kalten Lande mehr Geheimnisse bergen als jedes warme. Ihre Studien haben sie zu einer dunkleren Angelegenheit geführt, als sie erwartet hatte: dem Wahnsinn der {link:winterfall-furbolgs}Winterfelle{/link}.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Donova verfolgte den Wahnsinn der {link:winterfall-furbolgs}Winterfelle{/link} als Erste bis zu seinem Ursprung. Durch ihre Arbeit wurde bekannt, dass der Stamm ein Feuerwasser trank, das aus der Verderbnis des Teufelswalds gemacht war, und dass die heißen Quellen selbst ihre Wärme vielleicht Dämonen verdanken.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie erforscht die heißen Quellen von {link:frostfire-hot-springs}Frostfire{/link} und ihr seltsames Wasser.
• Sie erfährt, dass die {link:winterfall-furbolgs}Winterfelle{/link} die Quellen nutzen, um ihr Feuerwasser zu reinigen.
• Sie findet die Dämonen der flüsternden Schlucht und hält sie für den Ursprung der Wärme der Quellen.
• Sie verwahrt ein Schwert für ihren Freund {link:linken}Linken{/link} und weiß, wie es vollendet werden kann.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Das Spiel verrät nicht, woher Donova stammt oder welchem Orden sie dient, falls überhaupt einem.]=],
		},
	},
	chapters = {
		{
			title = "Das Feuerwasser der Winterfelle",
			hint = [=[Bringe der Gelehrten eine Flasche, die die Winterfelle fallen ließen.]=],
			text = [=[Die Flasche war leer bis auf ein paar Tropfen einer leuchtend grünen Flüssigkeit. Donova erkannte sie sofort als etwas, das dem Schlamm des {link:felwood}Teufelswalds{/link} glich. Die Spur führte zu den {link:camping}Lagern{/link} des Stammes der {link:deadwood-furbolgs}Totenwaldfelle{/link} und von dort zu den giftigen Schrecken des Eisenwalds. Als sie das Gift mit Quellwasser mischte, verlor es seine tödliche Wirkung, behielt aber seine Macht über jene, die es tranken. Nun verstand sie, warum die {link:winterfall-furbolgs}Winterfelle{/link} die Quellen bewachten: Sie brauchten sie, um ihr Feuerwasser herzustellen.]=],
		},
		{
			title = "Der Oberhäuptling",
			hint = "Mache dem ein Ende, der die Winterfelle befehligt.",
			text = [=[Die {link:winterfall-furbolgs}Winterfelle{/link} seien nie ein gewalttätiger Stamm gewesen, sagte Donova. Nur ihr Häuptling könne sie auf diesen Weg gebracht haben. Sie hoffte nicht, rückgängig zu machen, was geschehen war, doch sie glaubte, dass sie ohne ihren Anführer nicht weiter sinken würden. Der Häuptling trug ein Tagebuch bei sich, geschrieben in so groben Zeichen, dass sie es nicht lesen konnte. Sie schickte es nach Süden zu {link:kelek-skykeeper}Kelek Skykeeper{/link}, einem Druiden, der die {link:furbolgs}Furbolgs{/link} des Teufelswalds gut kennt.]=],
		},
		{
			title = "Der Ursprung der Quellen",
			hint = [=[Reise nach Süden, wo die Luft dick und der Himmel dunkel wird.]=],
			text = [=[Donova glaubte nicht, dass die Quellen allein von der Erde gewärmt wurden. Sie schickte einen Reisenden in den äußersten Süden von {link:winterspring}Winterspring{/link}, wo die Luft schwül wird und der Himmel sich verdunkelt. Dort lag die flüsternde Schlucht mit ihren Dämonen. Donova beobachtet die Quellen nun auf jedes weitere Zeichen ihres Einflusses.]=],
		},
	},
	mentions = {
		{
			text = [=[Ärger in {link:winterspring}Winterspring{/link}!, von Meggi Peppinrocker]=],
		},
		{
			text = [=[Die Bedrohung durch die {link:winterfall-furbolgs}Winterfelle{/link}]=],
		},
		{ text = "Feuerwasser der {link:winterfall-furbolgs}Winterfelle{/link}" },
		{ text = "Der Verderbnis verfallen" },
		{ text = "Rätselhafter Schleim" },
		{ text = "Giftige Schrecken" },
		{ text = "Läufer der {link:winterfall-furbolgs}Winterfelle{/link}" },
		{ text = "{link:high-chief-winterfall}Oberhäuptling Winterfell{/link}" },
		{ text = "Das letzte Stück" },
		{ text = "Worte des Oberhäuptlings" },
		{ text = "Die neuen Quellen, von {link:krakle}Krakle{/link}" },
		{ text = "Seltsame Quellen" },
		{ text = "Ein Geheimnis für alle" },
		{ text = "Das Videre-Elixier" },
		{ text = "Treffen am Grab" },
	},
	bonds = {
		{ id = "high-chief-winterfall", name = "Oberhäuptling Winterfell", note = "der Häuptling, dem sie Einhalt gebieten wollte" },
		{ id = "kelek-skykeeper", name = "Kelek Skykeeper", note = "liest für sie das Tagebuch des Häuptlings" },
		{ id = "linken", name = "Linken", note = "ihr Freund, der sein Gedächtnis verlor" },
