})

Translate("deDE", "rivern-frostwind", {
	title = "Rivern Frostwind",
	subtitle = "Ausbilder der Wintersäbler",
	found = "Unterhalb des Frostsäblerfelsens, im äußersten Norden",
	hint = [=[Finde die einsame Gestalt, die im äußersten Norden des Schnees große Katzen ausbildet.]=],
	allegiance = "Wintersäblerausbilder",
	aliases = { "Rivern" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Rivern Frostwind bildet die Frostsäbler von {link:winterspring}Winterspring{/link} zum Tragen von Reitern aus, mit nur einer großen weißen Katze namens Glacier als Gesellschaft. Diese sind die wildesten aller Säbler und am schwersten zu zähmen. Rivern gibt nicht jedem einfach einen. Ein Reiter muss sich das Vertrauen von Rivern und der Katzen gleichermaßen verdienen. Rivern bewahrt die alte Geschichte, wie {link:tyrande-whisperwind}Tyrande Whisperwind{/link} die Frostsäblerkönigin rettete, und verlangt in ihrem Namen Treue.]=],
		},
		{
			title = "Taten",
			text = [=[• Rivern füttert die jungen Säbler mit Chimären- und Bärenfleisch.
• Rivern vertreibt die {link:winterfall-furbolgs}Winterfelle{/link} vom {link:frostsaber-rock}Frostsäblerfelsen{/link}.
• Rivern schickt die Treuen gegen die Frostschlägerriesen, alte Feinde der Frostsäbler.]=],
		},
	},
	mentions = {
		{ text = "Proviant für die Frostsäbler" },
		{
			text = [=[Eindringlinge der {link:winterfall-furbolgs}Winterfelle{/link}]=],
		},
		{ text = "Wütende Riesen" },
	},
	bonds = {
		{ id = "shy-rotam", name = "Shy-Rotam", note = "die Frostsäblerkönigin" },
	},
})

Translate("deDE", "wynd-nightchaser", {
	title = "Wynd Nightchaser",
	subtitle = "Meister der Überlieferung von Starfall",
	found = "Starfall",
	hint = [=[Sprich mit dem Elfen von Starfall, der die alten Geschichten des Landes kennt.]=],
	allegiance = "Nachtelfen · Starfall",
	aliases = { "Wynd" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Wynd Nightchaser verbringt die meisten seiner Tage in {link:starfall-village}Starfall{/link}, und es gibt nur wenige, die die Ruinen von {link:winterspring}Winterspring{/link} besser kennen. Gelehrte aus dem {link:felwood}Teufelswald{/link} und aus {link:darnassus}Darnassus{/link} schicken ihre Schüler zu ihm. Er erzählt die Geschichte von {link:lake-kel-theril}Kel'Theril{/link} schlicht: ein verfluchtes Volk, gebunden an den Ort seines gescheiterten Rituals.]=],
		},
		{
			title = "Taten",
			text = [=[• Er erzählt von den Hochgeborenen, die eine heilige Reliquie stahlen und sie unter dem See zerschmetterten.
• Er schickt die Neugierigen zu {link:jaron-stoneshaper}Jaron Stoneshaper{/link}, der die Ruinen mit eigenen Augen gesehen hat.
• Er schickt den wiederhergestellten {link:crystal-of-zin-malor}Kristall von Zin-Malor{/link} nach {link:darnassus}Darnassus{/link}, damit er vor jenen bewahrt werde, die ihn missbrauchen würden.]=],
		},
	},
	chapters = {
		{
			title = "Der zurückgekehrte Kristall",
			hint = [=[Bringe den wiederhergestellten Kristall zurück nach Winterspring.]=],
			text = [=[Der Kristall konnte nie in seinen Tempel zurückkehren, denn der Tempel lag in Trümmern. Wynd urteilte, dass nur wenige der stärksten Magier ihn meistern könnten und dass er zu jenen gehöre, die ihn nicht missbrauchen würden. Er schickte ihn an {link:fandral-staghelm}Erzdruide Fandral Staghelm{/link}.]=],
		},
	},
	mentions = {
		{ text = "Auf nach {link:winterspring}Winterspring{/link}!" },
		{ text = "{link:starfall-village}Starfall{/link}" },
		{ text = "{link:lake-kel-theril}Die Ruinen von Kel'Theril{/link}" },
		{ text = "Reumütige Hochgeborene" },
		{ text = "Der {link:crystal-of-zin-malor}Kristall von Zin-Malor{/link}" },
	},
	bonds = {
		{ id = "jaron-stoneshaper", name = "Jaron Stoneshaper", note = "ein Gast in Starfall" },
		{ id = "fandral-staghelm", name = "Fandral Staghelm", note = "empfängt den Kristall" },
	},
})

