	},
})

Translate("deDE", "umbranse-the-spiritspeaker", {
	title = "Umbranse der Geistsprecher",
	subtitle = "Medium der Toten",
	found = "Eine einsame Behausung in den Hügeln östlich von Everlook",
	hint = [=[Suche den alten Medium, der allein in den östlichen Hügeln lebt.]=],
	allegiance = "Verbündeter des grünen Drachenschwarms",
	aliases = { "Umbranse" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Umbranse ist ein betagter Mensch, der als Einsiedler im östlichen {link:winterspring}Winterspring{/link} lebt. Er ist ein Medium, das für die Toten spricht, und der grüne Drache {link:itharius}Itharius{/link} zählt ihn zu den sterblichen Verbündeten seines Schwarms. Seine Künste sind selbst den Gelehrten fremd. Ein Buch, das er der {link:argent-dawn}Argentumdämmerung{/link} gab, hat ihre besten Gelehrten vor Rätsel gestellt.]=],
		},
		{
			title = "Taten",
			text = [=[• Er willigt ein, seine Kunst, mit den Toten zu sprechen, zu leihen, um den träumenden Drachen Eranikus zu erreichen.
• Er hat sein wirkungsvollstes Wahrsagegerät verloren, das man ihm gegen seinen Willen nahm.
• Er schrieb {i}Studien über das Geistsprechen{/i}, das nun in den Händen der {link:argent-dawn}Argentumdämmerung{/link} ist.]=],
		},
	},
	chapters = {
		{
			title = "In Eranikus' eigenen Worten",
			hint = "Komm auf Geheiß eines grünen Drachen zu dem Medium.",
			text = [=[Eranikus sei nicht tot, sagte Umbranse, nicht so, wie Sterbliche den Tod verstehen. Dennoch versprach er, dass der Drache eines Tages in seinen eigenen Worten Rat geben werde. Zuerst aber brauchte er Hilfe von jemandem, der jünger und stärker war, denn sein Wahrsagegerät war gestohlen worden.]=],
		},
	},
	mentions = {
		{ text = "In Eranikus' eigenen Worten" },
		{
			text = [=[{link:duke-nicholas-zverenhoff}Herzog Nicholas Zverenhoff{/link}, mit seinem Buch]=],
		},
	},
	bonds = {
		{ id = "itharius", name = "Itharius", note = "zählt ihn zu seinen Verbündeten" },
		{ id = "gregor-greystone", name = "Gregor Greystone", note = "schickte sein Buch an die Dämmerung" },
	},
})

