Translate("deDE", "lorax", {
	title = "Lorax",
	subtitle = "Satyr der Dämonenschmiede",
	found = "Ruinen im Süden der Frostwhisperschlucht",
	hint = [=[Suche den Satyr, der in der südlichen Schlucht zwischen Ruinen auf und ab geht.]=],
	allegiance = "Keine",
	sections = {
