			text = [=[Ranshalla stieg den Grat hinauf und entzündete fünf Fackeln in den Höhlen, wobei sie die Worte von {link:lake-kel-theril}Kel'Theril{/link} sprach. Der Altar erwachte. Er zeigte, dass die Wildkin keine bloßen Bestien waren. {link:fandral-staghelm}Erzdruide Fandral Staghelm{/link} sagte später, die Druiden hätten es lange gewusst: Die Wildkin sind Geschöpfe Elunes, erwählt, ihre heiligsten Stätten zu bewachen.]=],
		},
	},
	mentions = {
		{ text = "Findet Ranshalla" },
