Translate("deDE", "winterfall-furbolgs", {
	title = "Winterfelle",
	aliases = { "Winterfall", "Stamm der Winterfelle" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Winterfelle sind der Stamm der {link:furbolgs}Furbolgs{/link} von {link:winterspring}Winterspring{/link}. Sie waren kein gewalttätiges Volk, und lange waren sie die Verbündeten der {link:timbermaw-furbolgs}Holzschlund{/link}. Das hat sich geändert. Ihr Oberhäuptling hat seltsame Forderungen an sie gestellt, und nun fallen sie über jeden her, der sich nähert, Tier oder Reisenden, Elf oder Goblin. Sie unterhalten ein Lager in den Hügeln östlich von {link:everlook}Everlook{/link} und Lager nahe den heißen Quellen von {link:frostfire-hot-springs}Frostfire{/link}.]=],
		},
		{
			title = "Das Feuerwasser",
			text = [=[Der Wahnsinn hat einen Ursprung. Läufer des Stammes reisen durch die {link:timbermaw-hold}Holzschlundfeste{/link} zu den {link:furbolgs}Furbolgs{/link} der {link:deadwood-furbolgs}Totenwaldfelle{/link} im {link:felwood}Teufelswald{/link}, die selbst von teuflischer Verderbnis in den Wahnsinn getrieben sind. Sie bringen ein grünes Gebräu zurück, das aus dem Gift der giftigen Schrecken des Eisenwalds gemacht ist. Allein würde es sie töten. Mit dem Wasser der heißen Quellen gemischt, verliert es seine tödliche Wirkung, behält aber seine Macht, und wer es trinkt, wird größer und wilder. Darum bewachen die Winterfelle die Quellen so erbittert. Die Furbolgs tragen noch immer Geisterperlen, um böse Geister abzuwehren, doch die Perlen haben sie nicht vor dem bewahrt, was aus ihnen geworden ist.]=],
		},
	},
})

Translate("deDE", "crystal-of-zin-malor", {
	title = "Kristall von Zin-Malor",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Kristall von Zin-Malor ist eine Reliquie, die große arkane Kräfte fassen und beherrschen kann. Nur die wahrhaft Würdigen können ihn meistern, und nur eine Handvoll der stärksten Magier dürfte es hoffen. Er trägt den Namen des {link:temple-of-zin-malor}Tempels von Zin-Malor{/link}, der nun in {link:azshara}Azshara{/link} in Trümmern liegt. In alten Tagen stahlen ihn die Hochgeborenen von {link:lake-kel-theril}Kel'Theril{/link}, um seine Macht für sich selbst auszusaugen. Bei dem Versuch zersprang der Kristall in einer gewaltigen Explosion, und seine Stücke sanken unter das Eis des Sees. Die Hochgeborenen wurden verflucht, für immer dort zu bleiben, noch immer auf der Suche nach den Bruchstücken.]=],
		},
		{
			title = "Wiederhergestellt",
			text = [=[In der heutigen Zeit durchbrach die Spitzhacke eines Zwergs das Eis und förderte vier Bruchstücke zutage. Die Hochelfe {link:aurora-skycaller}Aurora Skycaller{/link} erkannte sie. Mit den heiligen Schriften der Hochgeborenen, die aus dem zerstörten Tempel in {link:azshara}Azshara{/link} geborgen worden waren, machte sie den Kristall wieder ganz. Er wurde einem Geist von {link:lake-kel-theril}Kel'Theril{/link} gezeigt, der das alte Verbrechen bereute, und dieser Geist fand Frieden. Der Kristall konnte nie in seinen Tempel zurückkehren. {link:wynd-nightchaser}Wynd Nightchaser{/link} aus {link:starfall-village}Starfall{/link} schickte ihn an {link:fandral-staghelm}Erzdruide Fandral Staghelm{/link} in {link:darnassus}Darnassus{/link}, der jene lobte, die ihn trugen, weil sie nicht versucht hatten, ihn selbst zu benutzen.]=],
		},
	},
})
